ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	"host": Mule::p("api.host"),
	"port": Mule::p("api.port"),
	"method": "GET",
	"basePath": Mule::p("api.dos.basepath"),
	"path": "/dos-recursion",
	"header": {
		"x-client-id": Mule::p("secure::api.clientId"),
		"x-client-secret": Mule::p("secure::api.clientSecret"),
		"x-correlation-id": uuid()
	},
	"queryParam": {
		"offset": (vars.offset + 200)
	},
	"uriParam": {},
	"body": {}
}

scripting:execute.scripting:code:
import org.mindrot.jbcrypt.BCrypt
def password = vars.bcryptPwd
// Hash the password with a cost factor of 4
def hashedPassword = BCrypt.hashpw(password, BCrypt.gensalt(4))
println "Hashed Password: $hashedPassword"
payload = hashedPassword

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
payload reduce (item, accumulator={}) ->
	accumulator ++ {
        (item."MemberID__c"): {
            "contactId": item."Id",
            "accountId": item."AccountId",
            "companyCode": item."Account"."CompanyCode__c"
        }
    }

scripting:execute.scripting:code:
import org.mindrot.jbcrypt.BCrypt
def password = "mySecurePassword"
// Hash the password with a cost factor of 10
def hashedPassword = BCrypt.hashpw(password, BCrypt.gensalt(10))
println "Hashed Password: $hashedPassword"

ee:variables.ee:set-variable:
%dw 2.0
output application/java
fun normalizeAddress(s: String) = upper(trim(s replace /[^a-zA-Z0-9 ]/ with "" replace /\s+/ with " "))
var accountMapByAddress = (payload groupBy normalizeAddress($.BillingStreet default ""))
    mapObject ((accounts, key) ->
        (key): ((accounts filter (!isEmpty($.ParentId default "")))[0] default accounts[0]).Id
    )
var accountMapByName = (payload groupBy upper($.Name default ""))
    mapObject ((accounts, key) ->
        (key): ((accounts filter (!isEmpty($.ParentId default "")))[0] default accounts[0]).Id
    )
var updateRecords = vars.firmRecords
    map {
        "DOS_License_Number_External_ID__c": $."license_number",
        "salesforce_Account_link__c":
            accountMapByAddress[normalizeAddress($."business_address_1" default "")] default
            accountMapByName[upper($."business_name" default "")]
    }
    filter (!isEmpty($.salesforce_Account_link__c))
---
{
    "objType": "DOS_Data__c",
    "extFieldName": "DOS_License_Number_External_ID__c",
    "records": updateRecords
}
